	/**
	 * Выполняем проверку количества записей перечня в перезаписи
	 *
	 * @note Именно здесь порок и вскрывался: строка черты со строкою свойств уходили
	 *       дословным переносом соседа сверху, а правленое значение сборка писала своею
	 *       записью - записей выходило три вместо двух
	 */
	ASSERT_EQ(back.root().size(), document.root().size()) << written;
